package org.eclipse.rdf4j.spin.function.spif;

import static org.assertj.core.api.Assertions.assertThat;

import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.model.vocabulary.FN;
import org.eclipse.rdf4j.model.vocabulary.SPIF;
import org.eclipse.rdf4j.query.algebra.FunctionCall;
import org.eclipse.rdf4j.query.algebra.ValueConstant;
import org.eclipse.rdf4j.query.algebra.Var;
import org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.ScalarEvaluationEffects;
import org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.ScalarEvaluationEffects.Effect;
import org.junit.jupiter.api.Test;

class InvokeTest {

	@Test
	void delegateChosenByArgumentCannotPromiseRepeatability() {
		assertThat(new Invoke().mustReturnDifferentResult()).isTrue();
	}

	@Test
	void registeredCallIsVolatileEvenForADeterministicDelegate() {
		FunctionCall call = new FunctionCall(SPIF.INVOKE_FUNCTION.stringValue(),
				new ValueConstant(SimpleValueFactory.getInstance().createIRI(FN.UPPER_CASE.stringValue())),
				new Var("value"));

		assertThat(ScalarEvaluationEffects.effectOf(call)).isEqualTo(Effect.VOLATILE);
	}
}
